use base64::{engine::general_purpose::STANDARD, Engine};
use rand::RngCore;
use ring::aead::{Aad, LessSafeKey, Nonce, UnboundKey, AES_256_GCM};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::{
    collections::BTreeMap,
    fs,
    path::PathBuf,
    sync::{Arc, RwLock},
};

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, PartialOrd, Ord)]
pub struct KeyScope {
    pub tenant_id: String,
    pub application_id: Option<String>,
    pub purpose: String,
}
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct KeyReference {
    pub provider: String,
    pub key_id: String,
    pub version: u64,
}
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct WrappedKey {
    pub nonce: String,
    pub ciphertext: String,
    pub algorithm: String,
}
#[derive(Debug, Clone, Serialize)]
pub struct KeyProviderHealth {
    pub provider: String,
    pub available: bool,
    pub active_key: String,
    pub rotation_due: bool,
}
pub trait KeyProvider: Send + Sync {
    fn active_key(&self, scope: &KeyScope) -> Result<KeyReference, String>;
    fn encrypt_dek(
        &self,
        scope: &KeyScope,
        dek: &[u8],
    ) -> Result<(KeyReference, WrappedKey), String>;
    fn decrypt_dek(
        &self,
        key: &KeyReference,
        wrapped: &WrappedKey,
        scope: &KeyScope,
    ) -> Result<Vec<u8>, String>;
    fn rotate(&self, scope: &KeyScope) -> Result<KeyReference, String>;
    fn health(&self, scope: &KeyScope) -> KeyProviderHealth;
}
#[derive(Serialize, Deserialize, Default)]
struct LocalKeys {
    active: BTreeMap<String, u64>,
    keys: BTreeMap<String, String>,
}
#[derive(Clone)]
pub struct LocalKeyProvider {
    path: PathBuf,
    root: Arc<[u8; 32]>,
    data: Arc<RwLock<LocalKeys>>,
}
fn scope_id(s: &KeyScope) -> String {
    format!(
        "{}|{}|{}",
        s.tenant_id,
        s.application_id.as_deref().unwrap_or("*"),
        s.purpose
    )
}
fn scope_hash(s: &str) -> String {
    Sha256::digest(s.as_bytes())[..6]
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}
fn aad(s: &KeyScope, k: &KeyReference) -> Vec<u8> {
    format!(
        "feltdb-kek-v1|{}|{}|{}|{}",
        scope_id(s),
        k.provider,
        k.key_id,
        k.version
    )
    .into_bytes()
}
impl LocalKeyProvider {
    pub fn load(path: impl Into<PathBuf>, root: [u8; 32]) -> Result<Self, String> {
        let path = path.into();
        let data = if path.exists() {
            serde_json::from_slice(&fs::read(&path).map_err(|_| "key provider unavailable")?)
                .map_err(|_| "key provider metadata invalid")?
        } else {
            LocalKeys::default()
        };
        Ok(Self {
            path,
            root: Arc::new(root),
            data: Arc::new(RwLock::new(data)),
        })
    }
    fn persist(&self, d: &LocalKeys) -> Result<(), String> {
        if let Some(p) = self.path.parent() {
            fs::create_dir_all(p).map_err(|_| "key provider unavailable")?;
        }
        let t = self.path.with_extension("tmp");
        fs::write(
            &t,
            serde_json::to_vec_pretty(d).map_err(|_| "key provider metadata invalid")?,
        )
        .map_err(|_| "key provider unavailable")?;
        fs::rename(t, &self.path).map_err(|_| "key provider unavailable".to_string())
    }
    fn material(&self, k: &KeyReference) -> Result<[u8; 32], String> {
        let d = self.data.read().map_err(|_| "key provider unavailable")?;
        let seed = STANDARD
            .decode(d.keys.get(&k.key_id).ok_or("key unavailable or revoked")?)
            .map_err(|_| "key provider metadata invalid")?;
        Ok(Sha256::digest([self.root.as_slice(), seed.as_slice()].concat()).into())
    }
    fn ensure(&self, s: &KeyScope) -> Result<KeyReference, String> {
        self.active_key(s).or_else(|_| self.rotate(s))
    }
}
impl KeyProvider for LocalKeyProvider {
    fn active_key(&self, s: &KeyScope) -> Result<KeyReference, String> {
        let d = self.data.read().map_err(|_| "key provider unavailable")?;
        let v = *d.active.get(&scope_id(s)).ok_or("no active key")?;
        Ok(KeyReference {
            provider: "local".into(),
            key_id: format!("key-{}-{v}", scope_hash(&scope_id(s))),
            version: v,
        })
    }
    fn encrypt_dek(&self, s: &KeyScope, dek: &[u8]) -> Result<(KeyReference, WrappedKey), String> {
        let kr = self.ensure(s)?;
        let material = self.material(&kr)?;
        let key = LessSafeKey::new(
            UnboundKey::new(&AES_256_GCM, &material).map_err(|_| "key provider unavailable")?,
        );
        let mut n = [0; 12];
        rand::thread_rng().fill_bytes(&mut n);
        let mut v = dek.to_vec();
        key.seal_in_place_append_tag(
            Nonce::assume_unique_for_key(n),
            Aad::from(aad(s, &kr)),
            &mut v,
        )
        .map_err(|_| "DEK wrap failed")?;
        Ok((
            kr,
            WrappedKey {
                nonce: STANDARD.encode(n),
                ciphertext: STANDARD.encode(v),
                algorithm: "AES-256-GCM".into(),
            },
        ))
    }
    fn decrypt_dek(
        &self,
        kr: &KeyReference,
        w: &WrappedKey,
        s: &KeyScope,
    ) -> Result<Vec<u8>, String> {
        if kr.provider != "local" {
            return Err("incompatible key provider".into());
        }
        let material = self.material(kr)?;
        let key = LessSafeKey::new(
            UnboundKey::new(&AES_256_GCM, &material).map_err(|_| "key provider unavailable")?,
        );
        let n: [u8; 12] = STANDARD
            .decode(&w.nonce)
            .map_err(|_| "wrapped key invalid")?
            .try_into()
            .map_err(|_| "wrapped key invalid")?;
        let mut v = STANDARD
            .decode(&w.ciphertext)
            .map_err(|_| "wrapped key invalid")?;
        let len = key
            .open_in_place(
                Nonce::assume_unique_for_key(n),
                Aad::from(aad(s, kr)),
                &mut v,
            )
            .map_err(|_| "DEK unwrap failed")?
            .len();
        v.truncate(len);
        Ok(v)
    }
    fn rotate(&self, s: &KeyScope) -> Result<KeyReference, String> {
        let mut d = self.data.write().map_err(|_| "key provider unavailable")?;
        let sid = scope_id(s);
        let v = d.active.get(&sid).copied().unwrap_or(0) + 1;
        let kid = format!("key-{}-{v}", scope_hash(&sid));
        let mut seed = [0; 32];
        rand::thread_rng().fill_bytes(&mut seed);
        d.keys.insert(kid.clone(), STANDARD.encode(seed));
        d.active.insert(sid, v);
        self.persist(&d)?;
        Ok(KeyReference {
            provider: "local".into(),
            key_id: kid,
            version: v,
        })
    }
    fn health(&self, s: &KeyScope) -> KeyProviderHealth {
        match self.active_key(s) {
            Ok(k) => KeyProviderHealth {
                provider: "local".into(),
                available: true,
                active_key: k.key_id,
                rotation_due: false,
            },
            Err(_) => KeyProviderHealth {
                provider: "local".into(),
                available: false,
                active_key: "uninitialized".into(),
                rotation_due: false,
            },
        }
    }
}
pub fn provider_from_environment(
    path: PathBuf,
    production: bool,
) -> Result<Arc<dyn KeyProvider>, String> {
    let kind = std::env::var("FELTDB_KEY_PROVIDER").unwrap_or_else(|_| "local".into());
    if kind != "local" && kind != "env" {
        return Err(format!("key provider '{kind}' is not installed"));
    }
    let material = std::env::var("FELTDB_MASTER_KEY")
        .or_else(|_| std::env::var("FELTDB_SECRET_KEY"))
        .map_err(|_| {
            if production {
                "production requires an explicit key provider and root key"
            } else {
                "FELTDB_MASTER_KEY is required; keys are never generated implicitly"
            }
        })?;
    Ok(Arc::new(LocalKeyProvider::load(
        path,
        Sha256::digest(material.as_bytes()).into(),
    )?))
}
